#!/usr/bin/env python3
# l3icons.py - Launcher3 quickstep drawables -> GJS icon data, through vd2js.py (same ops format).
#
#   python3 tools/l3icons.py NAME... > l3icondata.js
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vd2js as v

QUICKSTEP = os.environ.get('QUICKSTEP', 'ref/Launcher3/quickstep')   # Launcher3's quickstep/ in a checkout
out = ['// Generated by tools/l3icons.py from Launcher3 (Android 16, LineageOS 23.2) and its quickstep',
       '// drawables. Do not edit.', 'export const ICONS = {']
for name in sys.argv[1:]:
    rel = f'res/drawable/{name}.xml'
    # quickstep's own, or Launcher3's
    v.FWB = QUICKSTEP if os.path.exists(os.path.join(QUICKSTEP, rel)) else os.path.dirname(QUICKSTEP)
    chain = []
    vec = v.load_drawable(rel, 'res', name, chain)
    ops = []
    v.flatten(vec, (1, 0, 0, 1, *getattr(vec, 'inset', (0.0, 0.0))), vec.p['alpha'], ops, name)
    out.append(f"    // Launcher3/{'quickstep/' if v.FWB == QUICKSTEP else ''}{rel}")
    out.append(f"    '{name}': {{w: {v.js(vec.w)}, h: {v.js(vec.h)}, dw: {v.js(vec.dw)}, dh: {v.js(vec.dh)}, ops: [")
    out += [f'        {v.js(op)},' for op in ops]
    out.append('    ]},')
out.append('};')
print('\n'.join(out))
for icon, msg in dict.fromkeys(v.NOTES):
    print(f'{icon}: {msg}', file=sys.stderr)
